private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            {
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "1")
                {
                    e.Cancel = true;
                }
            }
}

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("DATEDOKGJENDJEKF") != null)
            {
                cnt++;
                xrTableCell1.Text = cnt.ToString();
                string llojDok = GetCurrentColumnValue("NIVELREGJISTRIMI").ToString();
                string nrDok = GetCurrentColumnValue("NRDOKGJENDJEKF").ToString();
                string idDok = GetCurrentColumnValue("IDDOKUMENTI").ToString();
                string url = AlphaWebReports.raporteUtil.ktheUrlDokumentiRaportKlientFurnitor( llojDok, idDok, nrDok, scopeID );
                if (url != "")
                {
                    xrTableCell1.NavigateUrl = url;
                    xrTableCell1.ForeColor = Color.SteelBlue;
                    xrTableCell1.Target = "_self";
                }
            }
}

