private void xrTableCell8_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (GetCurrentColumnValue("DEBIMONBAZE") != null && GetCurrentColumnValue("KREDIMONBAZE").ToString() != "")
            {
                if (cnt == 1)
                    vleraProgresive = vleraProgresive + gjendjameparekredi - gjendjameparedebi;
                vleraProgresive = vleraProgresive + Convert.ToDouble(GetCurrentColumnValue("KREDIMONBAZE").ToString()) - Convert.ToDouble(GetCurrentColumnValue("DEBIMONBAZE").ToString());
                xrTableCell8.Text = String.Format("{0:#,#.00}", vleraProgresive);
            }
}

